from collections import deque

def shortest_path(graph, source, target):
    # If the source is the same as the target, the path is trivial and distance is 0
    if source == target:
        return (0, [source])

    # Initialize distances and paths
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    paths = {node: [] for node in graph}

    # Queue for BFS
    queue = deque([source])

    while queue:
        current_node = queue.popleft()

        # Iterate through neighbors
        for neighbor, weight in graph.get(current_node, []):
            new_distance = distances[current_node] + weight

            # If a shorter path is found, update the distance and add the path
            if new_distance < distances[neighbor]:
                distances[neighbor] = new_distance
                paths[neighbor] = paths[current_node] + [neighbor]

                # If we have reached the target, break
                if neighbor == target:
                    return (distances[neighbor], paths[neighbor])

                queue.append(neighbor)

    # If we have not reached the target, the target is unreachable
    return (float('inf'), None)

