def shortest_path(graph, source, target):
    # Initialize the distance dictionary with infinity for all nodes except the source node
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    # Initialize the previous node dictionary
    previous_nodes = {node: None for node in graph}

    # Queue for BFS
    queue = [source]

    while queue:
        current = queue.pop(0)

        # Explore each neighbor of the current node
        for neighbor, weight in graph.get(current, []):
            distance_through_current = distances[current] + weight
            if distance_through_current < distances[neighbor]:
                distances[neighbor] = distance_through_current
                previous_nodes[neighbor] = current
                # Add the neighbor to the end of the queue
                queue.append(neighbor)

                # If we reach the target, we can stop the search
                if neighbor == target:
                    path = [neighbor]
                    while neighbor is not None:
                        neighbor = previous_nodes[neighbor]
                        path.insert(0, neighbor)
                    return (distances[target], path)

    # If we exit the loop without finding the target, it means the target is unreachable
    return (float('inf'), None)

