def shortest_path(graph, source, target):
    import heapq

    # Priority queue to hold paths (distance, node)
    queue = [(0, [source])]
    visited = set()

    while queue:
        (distance, path) = heapq.heappop(queue)

        if path[-1] not in visited:
            visited.add(path[-1])

            # If the target is reached, return the path
            if path[-1] == target:
                return (distance, path)

            # Explore neighbors
            for neighbor, weight in graph.get(path[-1], []):
                if neighbor not in visited:
                    new_path = path + [neighbor]
                    new_distance = distance + weight
                    heapq.heappush(queue, (new_distance, new_path))

    # If the target is unreachable, return infinity and None
    return (float("inf"), None)
