from collections import deque

def shortest_path(graph, source, target):
    # Initialize distances dictionary to store the shortest distance from source to each node
    distances = {node: float('inf') for node in graph}
    distances[source] = 0  # The distance to the source node itself is 0

    # Initialize a queue for BFS, containing tuples of (node, distance)
    queue = deque([(source, 0)])

    while queue:
        current_node, current_distance = queue.popleft()

        # If we've reached the target, return the distance and the path
        if current_node == target:
            path = []
            while current_node is not None:
                path.append(current_node)
                current_node = distances[current_node]
            return (current_distance, path[::-1])

        # Explore the neighbors
        for neighbor, weight in graph.get(current_node, []):
            distance = current_distance + weight

            # Only consider this new path if it's shorter
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                queue.append((neighbor, distance))

    # If we've exhausted the queue without finding the target, the target is unreachable
    return (float('inf'), None)

# Example usage:
graph_example = {
    'A': [('B', 1), ('C', 4)],
    'B': [('A', 1), ('C', 2), ('D', 5)],
    'C': [('A', 4), ('B', 2), ('D', 1)],
    'D': [('B', 5), ('C', 1)]
}

print(shortest_path(graph_example, 'A', 'D'))  # Should return (3, ['A', 'C', 'D'])
print(shortest_path(graph_example, 'A', 'E'))  # Should return (float('inf'), None)
